const $=s=>document.querySelector(s),login=$('#login'),dashboard=$('#dashboard'),loginForm=$('#login-form'),codeForm=$('#code-form'),authMessage=$('#auth-message');
const statusLabels={pending_confirmation:'Solicitação recebida',confirmed:'Agendamento confirmado',awaiting_documents:'Aguardando documentos',scheduled:'Videoconferência agendada',issuance_sent:'Pronto para emissão',completed:'Finalizado',cancelled:'Cancelado',rejected:'Recusado'};
const paymentLabels={pending:'Pagamento pendente',reported:'Comprovante recebido',confirmed:'Pagamento confirmado',not_found:'Pagamento não localizado',cancelled:'Pagamento cancelado',refunded:'Pagamento estornado'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number.isInteger(v)?new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100):'Sob consulta';
const date=v=>v?String(v).split('-').reverse().join('/'):'—';
const dateTime=v=>v?new Date(v).toLocaleString('pt-BR'):'—';
const maskCpf=v=>{const n=String(v||'');return n.length===11?`***.***.***-${n.slice(-2)}`:'—'};
const maskCnpj=v=>{const n=String(v||'');return n.length===14?`**.***.***/${n.slice(8,12)}-${n.slice(-2)}`:'—'};
function message(el,text,error=false){el.textContent=text;el.classList.toggle('error',error)}
async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Não foi possível concluir a solicitação.');return data}
loginForm.addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;message(authMessage,'Enviando código…');try{const body={protocol:e.currentTarget.elements.protocol.value.trim(),email:e.currentTarget.elements.email.value.trim()};const data=await api('/api/client/auth/request-code',{method:'POST',body:JSON.stringify(body)});message(authMessage,data.message);loginForm.hidden=true;codeForm.hidden=false;codeForm.elements.code.focus()}catch(err){message(authMessage,err.message,true)}finally{button.disabled=false}});
codeForm.addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;message(authMessage,'Verificando…');try{await api('/api/client/auth/verify-code',{method:'POST',body:JSON.stringify({protocol:loginForm.elements.protocol.value.trim(),email:loginForm.elements.email.value.trim(),code:e.currentTarget.elements.code.value})});await loadOrder()}catch(err){message(authMessage,err.message,true)}finally{button.disabled=false}});
$('#new-code').addEventListener('click',()=>{codeForm.hidden=true;loginForm.hidden=false;codeForm.reset();message(authMessage,'')});
$('#logout').addEventListener('click',async()=>{await api('/api/client/auth/logout',{method:'POST'});location.reload()});
async function loadOrder(){try{const {order}=await api('/api/client/order');render(order);login.hidden=true;dashboard.hidden=false;$('#logout').hidden=false;$('#client-email').textContent=order.email}catch(err){if(err.message!=='Acesso não autorizado.')message(authMessage,err.message,true)}}
function item(label,value,full=false){return `<div class="data-item${full?' full':''}"><span>${esc(label)}</span><strong>${esc(value||'—')}</strong></div>`}
function render(order){
  $('#order-protocol').textContent=order.protocol;$('#order-product').textContent=order.product_title;const chip=$('#order-status');chip.textContent=statusLabels[order.status]||order.status;chip.className='status-chip '+(['completed'].includes(order.status)?'green':['issuance_sent'].includes(order.status)?'yellow':['cancelled','rejected'].includes(order.status)?'red':'');
  const a=order.address||{},address=[a.street,a.number,a.extra,a.district,a.city&&a.state?`${a.city}/${a.state}`:a.city,a.zip&&`CEP ${a.zip}`].filter(Boolean).join(' · ');
  $('#order-data').innerHTML=[item('Titular / responsável',order.holder,true),item('Certificado',order.product_title),item('Tipo',order.person==='pj'?'Pessoa jurídica':'Pessoa física'),item('Finalidade',order.purpose,true),item('CPF',maskCpf(order.cpf)),order.person==='pj'?item('CNPJ',maskCnpj(order.cnpj)):'',order.company?item('Empresa',order.company,true):'',item('E-mail',order.email,true),item('WhatsApp',order.phone),item('Nascimento',date(order.birth)),item('Atendimento',order.mode),item('Data e horário',`${date(order.appointment_date)} às ${order.appointment_time}`),address?item('Endereço',address,true):'',item('Solicitação criada',dateTime(order.created_at),true)].join('');
  renderTimeline(order);renderPayment(order);renderAccess(order);
  const current=$('#proof-current');current.textContent=order.payment_proof_name?`Comprovante enviado: ${order.payment_proof_name} · ${dateTime(order.payment_proof_uploaded_at)}`:'';
}
function renderTimeline(order){const rank={pending_confirmation:0,confirmed:1,awaiting_documents:1,scheduled:2,issuance_sent:3,completed:4},current=rank[order.status]??0,stages=[['1','Pedido recebido'],['2','Agenda confirmada'],['3','Atendimento'],['4','Emissão']];$('#timeline').innerHTML=stages.map((s,i)=>`<div class="timeline-step ${i<current?'done':i===current?'current':''}"><span>ETAPA ${s[0]}</span><strong>${s[1]}</strong></div>`).join('')}
function renderPayment(order){const status=order.payment_status||'pending';$('#payment-title').textContent=paymentLabels[status]||status;$('#payment-amount').textContent=money(order.payment_amount_cents??order.price_cents);$('#payment-description').textContent=status==='confirmed'?`Confirmado em ${dateTime(order.payment_confirmed_at)}.`:status==='reported'?'Recebemos seu comprovante. A Agilize fará a conferência.':'O pedido permanecerá pendente até a conferência do pagamento.';const box=$('#pix-box');box.hidden=!order.payment_copy_paste;$('#pix-code').value=order.payment_copy_paste||''}
function renderAccess(order){const values=[];if(order.syngulari_protocol)values.push(item('Protocolo Syngulari',order.syngulari_protocol));if(order.video_url)values.push(`<div class="data-item"><span>VIDEOCONFERÊNCIA</span><strong><a href="${esc(order.video_url)}" target="_blank" rel="noopener">Abrir videoconferência ↗</a></strong></div>`);if(order.issuance_protocol)values.push(item('Código de emissão',order.issuance_protocol));if(order.issuance_protocol)values.push(`<div class="data-item"><span>ENDEREÇO PARA EMISSÃO</span><strong><a href="https://mp.syngularid.com.br" target="_blank" rel="noopener">Abrir página de emissão ↗</a></strong></div>`);$('#access-card').hidden=!values.length;$('#access-data').innerHTML=values.join('')}
$('#copy-pix').addEventListener('click',async()=>{const value=$('#pix-code').value;try{await navigator.clipboard.writeText(value)}catch{$('#pix-code').select();document.execCommand('copy')}$('#copy-pix').textContent='Código copiado';setTimeout(()=>$('#copy-pix').textContent='Copiar código PIX',1800)});
$('#proof-form').elements.proof.addEventListener('change',e=>$('#proof-label').textContent=e.target.files[0]?.name||'Selecionar PDF ou imagem');
$('#proof-form').addEventListener('submit',async e=>{e.preventDefault();const file=e.currentTarget.elements.proof.files[0],button=e.currentTarget.querySelector('button');if(!file)return;if(file.size>1024*1024){message($('#proof-message'),'O comprovante deve ter no máximo 1 MB.',true);return}button.disabled=true;message($('#proof-message'),'Enviando comprovante…');try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});await api('/api/client/proof',{method:'POST',body:JSON.stringify({name:file.name,type:file.type,data})});message($('#proof-message'),'Comprovante enviado com sucesso.');e.currentTarget.reset();$('#proof-label').textContent='Selecionar PDF ou imagem';await loadOrder()}catch(err){message($('#proof-message'),err.message,true)}finally{button.disabled=false}});
loadOrder();
